/**
 * HISTORY NODE 1 — VALIDATE_Query
 * Mode: Run Once for All Items
 *
 * Validates a records lookup and builds the positional parameter array for the
 * region's SQL. Nothing here interpolates caller input into a query string.
 *
 * ---------------------------------------------------------------------------
 * WHY PARAMETERS AND NOT STRING BUILDING
 * ---------------------------------------------------------------------------
 * site_id, asset_tag and status are caller-controlled and land in a WHERE
 * clause. Assembling that clause with an n8n expression would be a textbook
 * SQL-injection hole into the safety log — and this table is append-only
 * evidence, so a successful injection could read or destroy audit history.
 *
 * The queries therefore use a FIXED parameter count per region, with each
 * optional filter expressed as ($n IS NULL OR column = $n). Fixed arity means
 * the array this node emits always lines up with the placeholders, whatever
 * subset of filters the caller supplied. The cost is that Postgres may choose a
 * sequential scan over idx_faus_site_time on some plans; at this table's size
 * that is the right trade against a hand-built WHERE clause.
 *
 * ---------------------------------------------------------------------------
 * THE TWO REGIONS ARE NOT SYMMETRIC
 * ---------------------------------------------------------------------------
 * field_audit_us_logs has audit_id as its primary key plus asset_tag,
 * jurisdiction, deficiencies, code_basis and sign-off columns.
 *
 * field_audit_logs (India) was created ad hoc — there is no DDL for it in this
 * repo. Its real shape, confirmed against the live database:
 *
 *   id              integer  PRIMARY KEY (field_audit_logs_pkey)
 *   equipment_type  text
 *   status          text
 *   confidence      text
 *   observations    text
 *   violations      text      (a stringified JSON array)
 *   site_id         text
 *   audit_timestamp text      <-- NOT a timestamp type
 *   created_at      timestamptz DEFAULT now()
 *
 * Two consequences drive the India query:
 *
 * 1. `audit_timestamp` is TEXT. Comparing it against a timestamptz parameter
 *    raises "operator does not exist: text >= timestamp with time zone", so the
 *    date range filters on `created_at` — a real timestamptz — instead. The two
 *    are written milliseconds apart in the same n8n execution, so they are
 *    interchangeable for range purposes. `audit_timestamp` is still returned for
 *    display.
 *
 * 2. There IS a primary key after all: `id`. India records therefore have a
 *    stable identifier, exposed as `record_id`, which is the IND analogue of the
 *    US `audit_id`. `audit_id` itself stays rejected for IND — it is a minted
 *    string that only the US workflow produces.
 *
 * Migration 003 added asset_tag, inspector_id and image_url to this table, so
 * asset_tag is now a valid IND filter and India records finally carry evidence.
 * Rows written before that migration have NULL in all three.
 *
 * Authentication is handled by the Webhook node's Header Auth credential, not
 * here: the Code node sandbox blocks env access, so a secret compared in JS
 * would have to be committed to this file.
 */

const body = $input.first().json.body || {};

function reject(code, message, received) {
  return [{
    json: {
      route_index: 0,
      query_ok: false,
      error_code: code,
      error: message,
      received_value: received === undefined ? null : String(received).slice(0, 200)
    }
  }];
}

// ------------------------------------------------------------------- region
const region = String(body.region || '').trim().toUpperCase();
if (region !== 'US' && region !== 'IND') {
  return reject('REGION_INVALID', '"region" must be "US" or "IND".', body.region);
}

// -------------------------------------------------------------- text filters
function cleanText(value, maxLength) {
  if (value === undefined || value === null) return null;
  const out = String(value).trim();
  if (!out) return null;
  return out.slice(0, maxLength || 64);
}

const site_id = cleanText(body.site_id, 64);
const asset_tag = cleanText(body.asset_tag, 64);
const audit_id = cleanText(body.audit_id, 96);
const status_raw = cleanText(body.status, 32);

// Constrain status to the values the US CHECK constraint allows, so a typo
// returns an explicit error instead of an empty result the caller reads as
// "this site is clean".
const STATUSES = ['COMPLIANT', 'CONDITIONAL', 'NON-COMPLIANT', 'REINSPECT', 'ERROR'];
let status = null;
if (status_raw) {
  status = status_raw.toUpperCase();
  if (STATUSES.indexOf(status) === -1) {
    return reject(
      'STATUS_INVALID',
      'Unknown "status". Expected one of: ' + STATUSES.join(', ') + '.',
      status_raw
    );
  }
}

// ------------------------------------------------------- record_id (IND only)
// The India analogue of audit_id: field_audit_logs.id, an integer primary key.
let record_id = null;
if (body.record_id !== undefined && body.record_id !== null && String(body.record_id).trim() !== '') {
  if (region !== 'IND') {
    return reject(
      'FILTER_UNSUPPORTED_FOR_REGION',
      'record_id applies to the India log only. Use audit_id for US records.',
      body.record_id
    );
  }
  const raw = String(body.record_id).trim();
  if (!/^\d+$/.test(raw)) {
    return reject('RECORD_ID_INVALID', '"record_id" must be a positive integer.', body.record_id);
  }
  record_id = parseInt(raw, 10);
  if (!(record_id > 0)) {
    return reject('RECORD_ID_INVALID', '"record_id" must be a positive integer.', body.record_id);
  }
}

// audit_id is a MINTED identifier and exists only on the US table. India has no
// equivalent — it has an integer primary key, offered as record_id — so the
// filter is refused rather than quietly ignored. Silently dropping a filter
// returns rows the caller did not ask for, which on an audit log is worse than
// an error.
if (region === 'IND' && audit_id) {
  return reject(
    'FILTER_UNSUPPORTED_FOR_REGION',
    'The India audit log has no audit_id column. Identify India records by site_id and timestamp.',
    audit_id
  );
}

// -------------------------------------------------------------- date filters
// Accepts YYYY-MM-DD or a full ISO instant. Bare dates are anchored at UTC
// midnight; `to` is EXCLUSIVE so a caller passing the same day for both gets
// that whole day rather than nothing.
function parseBoundary(value, label) {
  if (value === undefined || value === null || String(value).trim() === '') {
    return { ok: true, value: null };
  }
  const raw = String(value).trim();
  if (!/^\d{4}-\d{2}-\d{2}([T ].*)?$/.test(raw)) {
    return {
      ok: false,
      message: '"' + label + '" must be YYYY-MM-DD or a full ISO timestamp.'
    };
  }
  const iso = /^\d{4}-\d{2}-\d{2}$/.test(raw) ? raw + 'T00:00:00.000Z' : raw;
  const parsed = new Date(iso);
  if (isNaN(parsed.getTime())) {
    return { ok: false, message: '"' + label + '" is not a real date.' };
  }

  // JavaScript's Date silently ROLLS OVER an impossible calendar date rather
  // than failing: new Date('2026-02-31') is 3 March 2026, and isNaN never fires.
  // Left unchecked, a caller asking for a date that does not exist would receive
  // results from a different range and never be told the range had moved. On an
  // audit log that is a wrong answer delivered confidently.
  //
  // Probing the Y-M-D through Date.UTC validates the calendar date on its own,
  // independent of any time or offset in the rest of the string.
  const ymd = raw.slice(0, 10).split('-');
  const year = Number(ymd[0]);
  const month = Number(ymd[1]);
  const day = Number(ymd[2]);
  const probe = new Date(Date.UTC(year, month - 1, day));
  if (
    probe.getUTCFullYear() !== year ||
    probe.getUTCMonth() + 1 !== month ||
    probe.getUTCDate() !== day
  ) {
    return {
      ok: false,
      message: '"' + label + '" is not a real calendar date (' + raw.slice(0, 10) + ').'
    };
  }

  return { ok: true, value: parsed.toISOString() };
}

const fromParsed = parseBoundary(body.from, 'from');
if (!fromParsed.ok) return reject('DATE_INVALID', fromParsed.message, body.from);

const toParsed = parseBoundary(body.to, 'to');
if (!toParsed.ok) return reject('DATE_INVALID', toParsed.message, body.to);

if (fromParsed.value && toParsed.value && fromParsed.value >= toParsed.value) {
  return reject(
    'DATE_RANGE_INVALID',
    '"from" must be earlier than "to". Note that "to" is exclusive.',
    fromParsed.value + ' .. ' + toParsed.value
  );
}

// ------------------------------------------------------------------ paging
// Capped so a caller cannot ask for the entire table in one response.
const MAX_LIMIT = 100;
let limit = parseInt(body.limit, 10);
if (isNaN(limit) || limit < 1) limit = 25;
if (limit > MAX_LIMIT) limit = MAX_LIMIT;

let offset = parseInt(body.offset, 10);
if (isNaN(offset) || offset < 0) offset = 0;

// Require at least one narrowing filter. An unbounded "give me everything"
// query against an append-only log is both a slow query and an enumeration
// primitive; the caller must say what they are looking for.
if (!site_id && !asset_tag && !audit_id && !record_id && !fromParsed.value && !toParsed.value) {
  return reject(
    'FILTER_REQUIRED',
    'Supply at least one of: site_id, asset_tag, audit_id, record_id, from, to. ' +
      'Unfiltered listing of the audit log is not permitted.',
    null
  );
}

// ------------------------------------------------------ positional parameters
// ORDER IS THE CONTRACT with the SQL in QUERY_US / QUERY_IND. Changing either
// side without the other silently mis-binds filters.
const params = region === 'US'
  //  $1        $2         $3        $4      $5                $6              $7     $8
  ? [site_id, asset_tag, audit_id, status, fromParsed.value, toParsed.value, limit, offset]
  //  $1        $2         $3          $4      $5                $6              $7     $8
  : [site_id, record_id, asset_tag, status, fromParsed.value, toParsed.value, limit, offset];

return [{
  json: {
    route_index: region === 'US' ? 1 : 2,
    query_ok: true,
    region: region,
    params: params,
    // Echoed back so the caller can confirm what was actually applied, and so
    // the UI can label a result set it may have re-fetched with defaults.
    applied: {
      site_id: site_id,
      asset_tag: asset_tag,
      audit_id: audit_id,
      record_id: record_id,
      status: status,
      from: fromParsed.value,
      to: toParsed.value,
      limit: limit,
      offset: offset
    },
    requested_at: new Date().toISOString()
  }
}];

/**
 * HISTORY NODE 2 — SHAPE_Results
 * Mode: Run Once for All Items
 *
 * Normalises rows from either region's table into the SAME object shape the
 * audit workflows return from SHAPE_Response.
 *
 * That is the whole point of this node. If a retrieved record matches the live
 * response contract, the dashboard can render history through the identical
 * report component — one renderer, one print stylesheet, one place for a bug to
 * live. Any divergence here becomes a second rendering path in the frontend.
 *
 * Receives items from QUERY_US or QUERY_IND, which have different column sets,
 * so region is read back from VALIDATE_Query rather than inferred from columns.
 */

const meta = $('VALIDATE_Query').first().json;
const region = meta.region;

const items = $input.all();

/**
 * A row is only real if it has a timestamp. Both query nodes run with
 * alwaysOutputData so this node still executes on a miss — otherwise a search
 * with no matches would abort the workflow and the caller would get an empty
 * body instead of an honest "0 results".
 */
function isRow(json) {
  return json && (json.audit_timestamp !== undefined && json.audit_timestamp !== null);
}

/** The India workflow stores violations as a stringified JSON array in a text column. */
function toArray(value) {
  if (Array.isArray(value)) return value;
  if (value === null || value === undefined) return [];
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return [];
    try {
      const parsed = JSON.parse(trimmed);
      return Array.isArray(parsed) ? parsed : [trimmed];
    } catch (e) {
      // Not JSON — treat the whole string as a single finding rather than
      // discarding it. Losing a violation line is not an acceptable failure.
      return [trimmed];
    }
  }
  return [];
}

/** jsonb columns arrive as objects, but tolerate a text column holding JSON. */
function toObject(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  if (typeof value === 'string' && value.trim()) {
    try {
      const parsed = JSON.parse(value);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
    } catch (e) { /* fall through */ }
  }
  return null;
}

function iso(value) {
  if (!value) return null;
  const d = new Date(value);
  return isNaN(d.getTime()) ? null : d.toISOString();
}

function shapeUs(r) {
  return {
    // ---- shared contract ----
    audit_id: r.audit_id,
    site_id: r.site_id,
    status: r.status,
    confidence: r.confidence,
    equipment_type: r.equipment_type,
    equipment_subtype: r.equipment_subtype,
    observations: r.observations,
    violations: toArray(r.violations),
    audit_timestamp: iso(r.audit_timestamp),

    // ---- findings ----
    critical: r.critical === true,
    risk_score: r.risk_score,
    severity_counts: {
      critical: r.critical_count,
      major: r.major_count,
      minor: r.minor_count
    },
    deficiencies: toArray(r.deficiencies),
    unverifiable_items: toArray(r.unverifiable_items),
    image_quality: r.image_quality,
    reinspect_required: r.reinspect_required === true,
    reinspect_reasons: toArray(r.reinspect_reasons),

    // ---- impairment ----
    // impairment_notice is NOT stored — BUILD_REPORT renders it at audit time
    // from the checklist, and only the basis is persisted. A retrieved record
    // therefore shows that an impairment was suspected and why, without the
    // full NFPA 25 Ch. 15 action checklist.
    impairment_suspected: r.impairment_suspected === true,
    impairment_basis: r.impairment_basis,

    // ---- remediation / governance ----
    sla_hours: r.sla_hours,
    remediation_due_at: iso(r.remediation_due_at),
    remediation_status: r.remediation_status,
    advisory_only: r.advisory_only !== false,
    signoff_status: r.signoff_status,
    signoff_by: r.signoff_by,
    signoff_at: iso(r.signoff_at),

    // ---- code basis actually applied at audit time ----
    // Stored as a snapshot, so a 2026 record stays interpretable after the
    // registry moves to a newer code edition.
    code_basis: toObject(r.code_basis) || {},

    // ---- context / evidence ----
    jurisdiction: r.jurisdiction,
    occupancy_type: r.occupancy_type,
    inspector_id: r.inspector_id,
    asset_tag: r.asset_tag,
    image_url: r.image_url,

    // ---- observability ----
    model_used: r.model_used,
    latency_ms: r.latency_ms,

    // Retrieved from the log, not produced by a live run. The UI uses this to
    // label the report as an archived record.
    retrieved: true,
    region: 'US'
  };
}

function shapeInd(r) {
  return {
    // Everything the US shape carries beyond the India table's columns is absent
    // by design, not missing by accident — those fields are emitted empty so the
    // renderer's optional-field handling does the work and no separate India code
    // path is needed.
    //
    // There is no minted audit_id, but there IS an integer primary key, so an
    // India record can still be addressed exactly. record_id is its analogue.
    audit_id: null,
    // ---- migration 004: the severity model ----
    // Emitted as null rather than 0 when absent. A record written before 004 has
    // no tier breakdown, and reporting "0 critical findings" for one would be a
    // fabrication — the severities were never computed. Null renders as absent;
    // zero renders as a clean bill.
    critical: r.critical === true,
    risk_score: r.risk_score === undefined ? null : r.risk_score,
    severity_counts: {
      critical: r.critical_count === undefined ? null : r.critical_count,
      major: r.major_count === undefined ? null : r.major_count,
      minor: r.minor_count === undefined ? null : r.minor_count
    },
    deficiency_count: r.deficiency_count === undefined ? null : r.deficiency_count,
    image_quality: r.image_quality === undefined ? null : r.image_quality,
    reinspect_required: r.reinspect_required === true,
    reinspect_reasons: toArray(r.reinspect_reasons),
    record_id: r.id === undefined ? null : r.id,
    site_id: r.site_id,

    // Added by migration 003. NULL on every row written before it, which is why
    // they stay optional rather than becoming required fields in the UI.
    asset_tag: r.asset_tag === undefined ? null : r.asset_tag,
    inspector_id: r.inspector_id === undefined ? null : r.inspector_id,
    image_url: r.image_url === undefined ? null : r.image_url,
    status: r.status,
    confidence: r.confidence,
    equipment_type: r.equipment_type,
    observations: r.observations,
    violations: toArray(r.violations),

    // audit_timestamp is a TEXT column on this table. It holds ISO-8601 from
    // toISOString(), so iso() normalises it, but fall back to created_at — the
    // real timestamptz, and what the range filter and ordering actually use —
    // rather than surfacing null if anything ever wrote a different format.
    audit_timestamp: iso(r.audit_timestamp) || iso(r.created_at),
    created_at: iso(r.created_at),

    // Structured findings, also from migration 004. Empty for pre-004 rows, whose
    // only record of what was wrong is the flat `violations` list above — the
    // report renderer already falls back to that when deficiencies is empty.
    deficiencies: toArray(r.deficiencies),
    unverifiable_items: toArray(r.unverifiable_items),

    // India resolves no code basis at run time — it is hardcoded in the prompt —
    // so nothing is snapshotted per row and there is nothing honest to put here.
    // The dashboard's regions.ts fallback supplies the statute text instead.
    code_basis: {},
    advisory_only: true,

    retrieved: true,
    region: 'IND'
  };
}

const rows = [];
for (let i = 0; i < items.length; i++) {
  const json = items[i].json;
  if (!isRow(json)) continue;
  rows.push(region === 'US' ? shapeUs(json) : shapeInd(json));
}

const limit = meta.applied ? meta.applied.limit : rows.length;

return [{
  json: {
    query_ok: true,
    region: region,
    count: rows.length,
    // A full page is indistinguishable from "exactly this many rows" without a
    // second COUNT(*), which is not worth the round trip. Signal it instead so
    // the UI can offer "next page" honestly rather than claiming a total.
    page_full: rows.length === limit,
    applied: meta.applied,
    rows: rows,
    retrieved_at: new Date().toISOString()
  }
}];

/**
 * ERROR_Handler — the synchronous half of error handling.
 * Mode: Run Once for All Items
 *
 * ONE source file, used verbatim by all three workflows (India, US, History), so
 * the error contract cannot drift between regions the way the notifier settings
 * did. Threaded in by patch_india_workflow.py, build_us_workflow.py and
 * build_history_workflow.py.
 *
 * ---------------------------------------------------------------------------
 * WHAT THIS IS FOR, AND WHAT IT IS NOT FOR
 * ---------------------------------------------------------------------------
 * This exists to answer the CALLER. Its entire job is to turn a node failure into
 * a structured response so no execution can end in silence — requirement 5 and 7
 * of the production checklist.
 *
 * It deliberately does NOT diagnose, log to a database, or send an alert. That is
 * the shared Error_Handler workflow's job (`settings.errorWorkflow`,
 * iLRmjyuk5mq1hqkB), which runs asynchronously after the caller already has a
 * response.
 *
 * The split is not tidiness, it is a latency and cost decision:
 *
 *   - The shared workflow makes an LLM diagnosis call. On the response path that
 *     costs a user 10-30 s before they learn anything, and AUDIT_TIMEOUT_MS is
 *     240 s, so a slow diagnosis converts a clean error into a proxy timeout.
 *   - If OpenRouter is what failed — the single most likely failure in this
 *     system — the diagnosis call fails too, in the exact case it was needed.
 *   - A ten-minute vision outage means a hundred failed audits. Error handling
 *     must not scale its cost with the size of the outage.
 *
 * So: respond here, cheaply and immediately. Diagnose there, later.
 *
 * ---------------------------------------------------------------------------
 * WHAT ROUTES HERE, AND WHAT MUST NEVER
 * ---------------------------------------------------------------------------
 * ROUTES HERE — anything on the path BEFORE the caller has been answered:
 *   every Code node's error output, every Switch node's fallbackOutput, and the
 *   History workflow's Postgres reads.
 *
 * MUST NEVER ROUTE HERE — anything on the notification branch AFTER the responder
 * has fired: SEND_Telegram, SEND_Slack, NOTIFY_OpsManager, the Gmail node. Those
 * carry `onError: continueRegularOutput` instead.
 *
 * The reason is concrete rather than stylistic: n8n permits exactly one response
 * per execution. A notifier failing after Respond_to_Webhook has already answered
 * would reach RESPOND_Error and n8n would throw "Webhook response already sent",
 * converting a lost Telegram message into a failed execution. That trades a minor
 * problem for a worse one.
 *
 * A consequence worth stating plainly: a Telegram send that fails after the
 * response is sent cannot be reported to the caller, and is currently only visible
 * in the n8n execution list. Surfacing it belongs to the execution-logging work
 * (checklist item 6), which will record `alert_sent` per channel.
 *
 * ---------------------------------------------------------------------------
 * WHY THIS IS A CODE NODE AND NOT A SET NODE
 * ---------------------------------------------------------------------------
 * The checklist asks for a "Set node". It is a Code node on purpose, following the
 * hard-won rule recorded in the same document: Set node assignments sometimes
 * render empty in the n8n UI after import even when the JSON looks correct.
 *
 * That failure mode is survivable in a content pipeline. Here it would mean the one
 * node responsible for reporting failures silently reporting nothing — the worst
 * possible node to have that bug in. A Code node's body is either present or it is
 * a syntax error, and `test_*.mjs` asserts byte equality between the JSON and this
 * file, so it cannot drift unnoticed.
 */

const item = $input.first() || {};
const j = item.json || {};

/**
 * n8n's error output shape is not stable across node types and versions. It may
 * arrive as `error` (string or object), `$error`, or `error.message`, and the
 * failing node may appear at `error.node.name` or not at all.
 *
 * Read defensively and never throw. An error handler that throws while handling an
 * error produces exactly the silent failure it exists to prevent, so every branch
 * below has a fallback and none of them can raise.
 */
function firstString(candidates, fallback) {
  for (let i = 0; i < candidates.length; i++) {
    const v = candidates[i];
    if (typeof v === 'string' && v.trim()) return v.trim().slice(0, 500);
  }
  return fallback;
}

const raw = (j.error && typeof j.error === 'object') ? j.error
          : (j.$error && typeof j.$error === 'object') ? j.$error
          : {};

const error_message = firstString([
  raw.message,
  raw.description,
  typeof j.error === 'string' ? j.error : null,
  typeof j.$error === 'string' ? j.$error : null,
  j.message
], 'An unexpected error occurred while processing this request.');

/**
 * The failing node's name.
 *
 * `$prevNode.name` is the reliable source and the others are fallbacks, which is the
 * reverse of what the first version of this file assumed. In practice n8n hands the
 * error branch an item whose `error` is a plain STRING — verified on a live forced
 * failure, where every structured candidate below came back empty and this node
 * reported "unknown". `$prevNode` is the node that fed this input, which for an
 * error output is by definition the node that failed.
 *
 * Guarded with `typeof` rather than assumed: `typeof` on an undeclared identifier
 * returns 'undefined' instead of throwing, so this is safe in a restricted `vm`
 * where the global may be absent, and safe in the offline harness which does not
 * provide it.
 */
const prev = typeof $prevNode !== 'undefined' && $prevNode ? $prevNode : null;

const error_node = firstString([
  prev && prev.name,
  raw.node && typeof raw.node === 'object' ? raw.node.name : null,
  typeof raw.node === 'string' ? raw.node : null,
  raw.nodeName,
  j.error_node
], 'unknown');

// Output 1 on a node with continueErrorOutput is its error branch, so this
// distinguishes "the node threw" from "a router sent us its fallback".
const error_output_index = prev && typeof prev.outputIndex === 'number'
  ? prev.outputIndex
  : null;

const error_type = firstString([
  raw.name,
  raw.errorType,
  j.error_type,
  // A Switch node's fallbackOutput is not an exception: it means the routing value
  // was one nobody anticipated. Naming it distinctly matters, because the fix is a
  // different fix — the router needs a branch, not the failing node repairing.
  j.validation_ok !== undefined ? 'UNROUTABLE_VALUE' : null
], 'WORKFLOW_ERROR');

const workflow_name = typeof $workflow !== 'undefined' && $workflow && $workflow.name
  ? String($workflow.name)
  : 'unknown';

/**
 * Identity, so a support request has something to quote and the row can be found.
 *
 * The error item carries the FAILING node's input, not the original request. When
 * SHAPE_Response fails its input is LOG_Audit's row echo, which has an `id` but no
 * `audit_id` and no `site_id` — verified on a live forced failure, where both came
 * back null and the response was consequently untraceable.
 *
 * So fall back to reading the validator by name. The try/catch is deliberate and
 * narrow: `$('NodeName')` throws when that node has not executed, which is exactly
 * the case when the validator itself is what failed. Swallowing that is correct
 * here because this is optional enrichment — an error handler that threw while
 * reaching for a nicety would produce the silent failure it exists to prevent.
 *
 * Both regions' validators are tried because this one file serves all three
 * workflows; History has no audit_id at all, and null is the honest answer there.
 */
/**
 * A first attempt at this used `$(name).first().json[field]` inside a try/catch and
 * returned null on failure. On a live forced error it returned null even though
 * VALIDATE_Input had demonstrably run and was listed among the node's inputs — and
 * because the catch was silent, the reason was invisible.
 *
 * Two changes. Several access patterns are tried, because `.first()` resolves paired
 * items and item pairing is exactly what an error branch breaks, whereas
 * `.all()[0]` does not. And whatever goes wrong is now RECORDED rather than
 * swallowed, so a failure explains itself on the next run instead of requiring
 * another round of guessing.
 *
 * The try/catch is still correct: `$('NodeName')` throws when that node has not
 * executed, which is the normal case when the validator itself is what failed. This
 * is optional enrichment, and a handler that threw while reaching for a nicety would
 * cause the silent failure it exists to prevent.
 */
const lookupNotes = [];

function fromValidator(field) {
  const names = ['VALIDATE_Input', 'VALIDATE_Query'];
  for (let i = 0; i < names.length; i++) {
    const name = names[i];

    // `.all()[0]` first: it does not go through paired-item resolution, which is the
    // most likely reason the previous version failed inside an error branch.
    const attempts = [
      function () { return $(name).all()[0].json[field]; },
      function () { return $(name).first().json[field]; },
      function () { return $(name).item.json[field]; }
    ];

    for (let a = 0; a < attempts.length; a++) {
      try {
        const v = attempts[a]();
        if (typeof v === 'string' && v.trim()) return v.trim().slice(0, 200);
        if (v !== undefined && v !== null) return String(v).slice(0, 200);
        lookupNotes.push(name + '[' + a + ']:' + field + '=empty');
      } catch (e) {
        lookupNotes.push(name + '[' + a + ']:' + String((e && e.message) || e).slice(0, 90));
      }
    }
  }
  return null;
}

const audit_id = firstString([j.audit_id, raw.audit_id], null) || fromValidator('audit_id');
const site_id = firstString([j.site_id, raw.site_id], null) || fromValidator('site_id');

const timestamp = new Date().toISOString();

return [{
  json: {
    // ---- the response contract, per checklist item 4 ----------------------
    success: false,
    error: error_message,
    code: error_type,
    timestamp: timestamp,

    // ---- what item 5 requires an error handler to capture ------------------
    error_type: error_type,
    error_node: error_node,
    error_output_index: error_output_index,
    error_message: error_message,
    workflow_name: workflow_name,

    // ---- identity, where the failure happened late enough to have it -------
    audit_id: audit_id,
    site_id: site_id,

    // Why the identity lookup failed, when it did. Present only on failure, so a
    // successful run stays clean. This exists because a silent catch already cost
    // one round of guessing about why audit_id came back null on a live error.
    identity_lookup: (audit_id === null && lookupNotes.length)
      ? lookupNotes.slice(0, 6).join(' | ')
      : undefined,

    // This project does not certify anything, and an error is not an exception to
    // that. A caller must not read a failed audit as an absent finding.
    advisory_only: true,
    status: 'ERROR'
  }
}];

/**
 * BUILD_ErrorAlert — turns a CAUGHT error into the payload the shared Error_Handler
 * workflow expects.
 * Mode: Run Once for All Items
 *
 * ONE source file used verbatim by all three workflows (India, US, History), for the
 * same reason shared_error_handler.js is: the alert contract must not drift between
 * regions. Threaded in by patch_india_workflow.py, build_us_workflow.py and
 * build_history_workflow.py.
 *
 * ---------------------------------------------------------------------------
 * WHY THIS EXISTS AT ALL — THE GAP IT CLOSES
 * ---------------------------------------------------------------------------
 * n8n runs a workflow's `settings.errorWorkflow` ONLY when an execution ends in
 * status *error*. A node with onError: continueErrorOutput whose error branch
 * completes leaves the execution *successful*. Every failable node in these three
 * workflows routes its error output to ERROR_Handler, so every failure they are
 * designed to survive ends as a SUCCESSFUL execution — and the shared Error_Handler
 * is never invoked for any of them.
 *
 * The consequence, before this node existed: ERROR_Handler -> RESPOND_Error ->
 * nothing. The caller received a clean HTTP 500 with a structured body, and the
 * operator was told NOTHING. No error_log row, no Telegram, no Slack. A vision
 * outage, a parse drift, a database outage or a validator crash was visible only to
 * whoever happened to be using the dashboard at the time.
 *
 * Verified on the live India workflow: the only reachable nodes that could produce an
 * *uncaught* failure are the webhook, two routers, three responders and
 * ERROR_Handler itself. DOWNLOAD_Image and EXTRACT_Base64 — the two plausible
 * failure points — are both disabled AND orphaned, so they can never run. Registering
 * the errorWorkflow therefore covers almost nothing here on its own. This node is
 * what actually makes operator alerting work.
 *
 * ---------------------------------------------------------------------------
 * WHY IT SITS AFTER RESPOND_Error, NOT BESIDE IT
 * ---------------------------------------------------------------------------
 * The caller must be answered first. Downstream-of-the-responder is the only
 * placement that GUARANTEES that ordering: a second branch off ERROR_Handler would
 * be ordered by n8n's execution-order heuristics, and correctness that depends on
 * canvas position is not correctness.
 *
 * CALL_ErrorHandler then runs with waitForSubWorkflow: false, so the diagnosis is
 * genuinely fire-and-forget. That matters twice over: the caller has already been
 * answered, and this execution does not stay open holding a worker slot while an LLM
 * thinks for 10-30 s against an AUDIT_TIMEOUT_MS of 240 s.
 *
 * ---------------------------------------------------------------------------
 * WHY IT READS $('ERROR_Handler') AND NOT $json
 * ---------------------------------------------------------------------------
 * Its input comes from RESPOND_Error, and what a respondToWebhook node emits on its
 * output is NOT something this file is willing to assume. It might pass its input
 * through, it might emit the response body, it might emit nothing. Reading the
 * handler by name makes that question irrelevant — a class of bug this project has
 * already paid for once, when ERROR_Handler read $json and got LOG_Audit's row echo
 * instead of the audit, which is why audit_id came back null on a live failure.
 *
 * RESPOND_Error carries alwaysOutputData: true so that "it might emit nothing" cannot
 * silently stop this chain. An empty item still triggers this node, and this node
 * does not care what is in it.
 *
 * ---------------------------------------------------------------------------
 * THE FIELD NAMES ARE NOT NEGOTIABLE
 * ---------------------------------------------------------------------------
 * Error_Handler's GENERATE_ErrorID reads a FLAT payload: workflow_name, run_id,
 * client_id, error_node, error_message, error_type, execution_url. Those exact names.
 * Its other entry point — the native Error Trigger — receives a completely different
 * shape ({ execution: {...}, workflow: {...} }), and the flat branch is the one this
 * node targets, so the alert will correctly report Source: executeWorkflow rather
 * than errorTrigger. See agentic-dev-stack PR #745.
 *
 * run_id <- audit_id and client_id <- site_id are deliberate: error_log's own columns
 * are generic, and mapping our identity onto them is what makes a row traceable back
 * to one audit of one building instead of being a nameless stack trace. History has
 * no audit_id at all and honestly reports 'unknown'.
 */

// The base URL is hardcoded rather than derived. A Code node has no reliable access
// to n8n's public URL: $env is blocked by configuration on some deployments, and
// there is no built-in that exposes it. A wrong link is worse than none, so if the
// ids are unavailable this emits '' and Error_Handler omits the link line entirely
// rather than printing a broken one.
const N8N_BASE_URL = 'https://n8n.kratuailabs.com';

/**
 * `$('NodeName')` THROWS when the named node has not executed. That cannot happen on
 * this path — ERROR_Handler is the only way to reach RESPOND_Error — but an error
 * handler that threw while assembling an error report would manufacture the silent
 * failure this whole chain exists to prevent. So it is guarded, and the guard is not
 * silent: a lookup failure still produces a payload, one that says so.
 */
let handler = {};
let lookupNote = '';
try {
  const rows = $('ERROR_Handler').all();
  handler = (rows && rows[0] && rows[0].json) ? rows[0].json : {};
} catch (e) {
  lookupNote = String((e && e.message) || e).slice(0, 120);
}

function str(value, fallback) {
  if (value === undefined || value === null) return fallback;
  const out = String(value).trim();
  return out === '' ? fallback : out;
}

// ------------------------------------------------------------- execution link
let execution_url = '';
try {
  const wfId = (typeof $workflow !== 'undefined' && $workflow) ? $workflow.id : null;
  const exId = (typeof $execution !== 'undefined' && $execution) ? $execution.id : null;
  if (wfId && exId) {
    execution_url = N8N_BASE_URL + '/workflow/' + wfId + '/executions/' + exId;
  }
} catch (e) {
  execution_url = '';
}

// error_message is capped because it is bound into an INSERT and then into three
// alert channels. Error_Handler's INSERT uses the array parameter form, so a comma in
// here is safe — but an unbounded provider response body is not.
const error_message = str(handler.error_message || handler.error, 'Unknown error')
  .slice(0, 2000);

return [{
  json: {
    // ---- exactly the names Error_Handler.GENERATE_ErrorID reads ------------
    workflow_name: str(handler.workflow_name, 'unknown'),
    run_id: str(handler.audit_id, 'unknown'),
    client_id: str(handler.site_id, 'unknown'),
    error_node: str(handler.error_node, 'unknown'),
    error_message: lookupNote
      ? error_message + ' [BUILD_ErrorAlert could not read ERROR_Handler: ' + lookupNote + ']'
      : error_message,
    error_type: str(handler.error_type, 'WORKFLOW_ERROR'),
    execution_url: execution_url
  }
}];
